import { useMemo, useState } from 'react';
import { JxTable, JxPagination, JxBadge } from '@jinx-ui/react';

interface User {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);
  const pageCount = Math.ceil(users.length / PAGE_SIZE) || 1;

  const visibleUsers = useMemo(
    () => users.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE),
    [users, page]
  );

  return (
    <div>
      <JxTable>
        <thead>
          <tr>
            <th>Имя</th>
            <th>Роль</th>
            <th>Статус</th>
          </tr>
        </thead>
        <tbody>
          {visibleUsers.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <JxBadge tone={user.active ? 'success' : 'default'} dot>
                  {user.active ? 'Активен' : 'Отключён'}
                </JxBadge>
              </td>
            </tr>
          ))}
        </tbody>
      </JxTable>
      <JxPagination total={pageCount} page={page} onPageChange={setPage} />
    </div>
  );
}

